  String titleColHtml = '<TD COLSPAN=2 ALIGN=LEFT WIDTH=100% BGCOLOR=TEAL>';
  String rowHtml = '<TR>';
  String propColHtml = '<TD WIDTH=30% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>';
  String valColHtml = '<TD WIDTH=70% BGCOLOR=LIGHTGREEN>';
  String tmpString = '';
  bool isNiStepType = false;
  String execFlow = '';
  String stepKeyName = '';
  int blockLevel = 0;
}

/// Sequence `Step Doc`.
Future<ts.Status> stepDoc({
  dynamic step,
  ts.Ref<String>? docResult,
  double totalNumSteps = 0,
  ts.Ref<int>? stepsSoFar,
  ts.Ref<int>? previousBlockLevel,
}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  final stepsSoFarRef = stepsSoFar ?? ts.Ref<int>(0);
  final previousBlockLevelRef = previousBlockLevel ?? ts.Ref<int>(0);
  final locals = _StepDocLocals();
  final run = ts.SequenceRun();
  final dynamic getStepTypeNameResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'PassFail': true,
    'ReportText': '',
    'Common': ts.PropObj(),
  });

  skipToBeginOfMultipleLimits:
  {
    final outputs = await ts.callActiveX(step, 'Step.BlockLevel'); // Get Block Level
    locals.blockLevel = outputs['Return Value'] as int;
    if (locals.blockLevel > previousBlockLevelRef.value) {
      docResultRef.value += '<BLOCKQUOTE>'; // Indent For Block
    }
    if (locals.blockLevel < previousBlockLevelRef.value) {
      docResultRef.value += '</BLOCKQUOTE>'; // Unindent For Block
    }
    previousBlockLevelRef.value = locals.blockLevel; // Remember Last Block Level
    stepsSoFarRef.value += 1; // Update StepsSoFar
    await ts.callDll(
      '\$(Platform)\\DocSupport.dll',
      'UpdateDocProgressPercent',
      inputs: {'percent_done': stepsSoFarRef.value / totalNumSteps * 100},
    ); // Update Percent Done
    ts.eval(
      'Parameters.DocResult += "<BLOCKQUOTE>" + Locals.TableHTML + Locals.RowHTML + Locals.TitleColHTML +\n	"<FONT COLOR=WHITE SIZE=+2><B>" +\n	GetResourceString("SEQ_FILE_DOC", "DOC_STEP_NAME") +\n	NameOf(Parameters.Step) + "</B></FONT>\\n"\n',
    ); // Step Header
    final outputs2 = await ts.callDll(
      '\$(Platform)\\DocSupport.dll',
      'GetStepTypeName',
      inputs: {'step': step, 'stringObjToStoreResult': locals.stepTypeName, 'isNIStepType': locals.isNiStepType},
    ); // Get StepType Name
    locals.isNiStepType = outputs2['isNIStepType'] as bool;
    getStepTypeNameResult.Status = ts.truthy(getStepTypeNameResult.PassFail) ? 'Passed' : 'Failed';
    run.record(getStepTypeNameResult.Status);
    final outputs3 = await ts.callActiveX(step, 'Step.AdapterKeyName'); // GetStepKeyName
    locals.stepKeyName = outputs3['Return Value'] as String;
    locals.tmpString = ts.resourceString('Adapter Names', locals.stepKeyName); // Process Adapter Name
    ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")');
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")');
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")');
    ts.eval(
      'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\nStr(ResStr("SEQ_FILE_DOC", "DOC_STEP_TYPE_AND_ADAPTER"), "%-30s") +\nLocals.ValColHTML +\nResStr("STEPTYPE_NAMES", Locals.StepTypeName, Locals.StepTypeName) + \n", " + Locals.tmpString + "\\n"\n',
    ); // Step Type, Adapter Name
    final outputs4 = await ts.callActiveX(
      step,
      'Step.GetDescriptionEx',
      inputs: {'options': ts.eval('1 \' long description')},
    ); // Get Step Desc
    locals.tmpString = outputs4['Return Value'] as String;
    ts.eval('FindAndReplace(Locals.tmpString, "<", "&lt;")'); // Process Desc
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")');
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")');
    docResultRef.value +=
        '${locals.rowHtml + locals.propColHtml + ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_DESC') + locals.valColHtml + locals.tmpString}\n'; // Step Description
    ts.eval('Locals.tmpString = CommentOf(Parameters.Step)'); // Process Comment
    ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")');
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")');
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")');
    if (ts.cond('CommentOf(Parameters.Step) != ""')) {
      docResultRef.value +=
          '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_COMMENT'), '%-30s') + locals.valColHtml + locals.tmpString}\n'; // Comment
    }
    if (ts.cond('PropertyExists("Parameters.Step.InBuf") ? Parameters.Step.InBuf != "" : False')) {
      locals.tmpString = step.InBuf as String; // Process InBuf
      ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")');
      ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")');
      ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")');
    }
    if (ts.cond('PropertyExists("Parameters.Step.InBuf") ? Parameters.Step.InBuf != "" : False')) {
      docResultRef.value +=
          '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_INBUF'), '%-30s') + locals.valColHtml + locals.tmpString}\n'; // InBuf
    }
    final docResultRef2 = ts.Ref<String>(docResultRef.value);
    await writeRequirementsElements(requirements: step.TS.Requirements, docResult: docResultRef2); // Add Requirements
    docResultRef.value = docResultRef2.value;
    docResultRef.value +=
        '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_LOAD_AND_UNLOAD_OPTION'), '%-30s') + locals.valColHtml + ts.resourceString('LOAD OPTION STRINGS', step.TS.LoadOpt)}, ${ts.resourceString('UNLOAD OPTION STRINGS', step.TS.UnloadOpt)}\n'; // Load and Unload Option
    if (step.TS.ResultOption != 1) {
      docResultRef.value +=
          '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_RECORD_RESULTS'), '%-30s') + locals.valColHtml + (step.TS.ResultOption == 0 ? ts.resourceString('STEP_PROP_DLG', 'RESULT_RECORDING_OPTION_DISABLED') : (step.TS.ResultOption == 1 ? ts.resourceString('STEP_PROP_DLG', 'RESULT_RECORDING_OPTION_ENABLED') : ts.resourceString('STEP_PROP_DLG', 'RESULT_RECORDING_OPTION_ENABLED_OVERRIDE_SEQUENCE_SETTING')))}\n'; // Record Results
    }
    if (!ts.truthy(step.TS.StepFCSeqF)) {
      docResultRef.value +=
          '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_STEP_FAIL_SEQ_FAIL'), '%-40s') + locals.valColHtml + ts.str(step.TS.StepFCSeqF)}\n'; // Step Fail Causes Seq Fail
    }
    if (ts.truthy(step.TS.IgnoreRTE)) {
      docResultRef.value +=
          '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_IGNORE_RTE'), '%-30s') + locals.valColHtml + ts.str(step.TS.IgnoreRTE)}\n'; // Ignore Run-Time Error
    }
    if (ts.cond('PropertyExists("Parameters.Step.Result.Measurement")')) {
      break skipToBeginOfMultipleLimits;
    }
    if (ts.cond('PropertyExists("Parameters.Step.Limits.String") ')) {
      locals.tmpString = step.Limits.String as String; // Process String Limit
      ts.eval('\nFindAndReplace(Locals.tmpString, "<", "&lt;")');
      ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")');
      ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")');
    }
    if (ts.cond('PropertyExists("Parameters.Step.Limits.String") ')) {
      docResultRef.value +=
          '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT_STRING'), '%-30s') + locals.valColHtml + locals.tmpString}\n'; // String Limit
    }
    if (ts.cond('PropertyExists("Parameters.Step.DataSource")')) {
      ts.eval(
        'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_DATASOURCE"), "%-30s") +\n	Locals.ValColHTML +\n	LocalizeExpression(Parameters.Step.DataSource) + "\\n"\n',
      ); // Data Source
    }
  }
  // --- Begin of Multiple Limits ---
  if (ts.cond(
    'AllOf(Locals.StepTypeName == "NI_MultipleNumericLimitTest", PropertyExists("Parameters.Step.Result.Measurement"))',
  )) {
    await writeMultipleNumericLimitLimits(); // Add Multiple Numeric Limits
  }
  final outputs5 = await ts.callActiveX(
    step,
    'Step.GetExecutionFlowString',
    inputs: {'options': ts.eval('0x1 \' StepDescOption_Long')},
  ); // Get Execution Flow
  locals.execFlow = outputs5['Return Value'] as String;
  if (locals.execFlow != '') {
    docResultRef.value +=
        '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_EXEC_FLOW'), '%-30s') + locals.valColHtml}<XMP>${locals.execFlow}</XMP>\n'; // Execution Flow
  }
  docResultRef.value += '</TABLE></BLOCKQUOTE>\n'; // Step Footer

  return run.status;
}

class _WriteSubpropertiesLocals {
  int numSubproperties = 0;
  int i = 0;
  String subpropName = '';
  String subpropLookupStr = '';
  bool isHidden = false;
  int subpropFlags = 0;
}

/// Sequence `Write Subproperties`.
Future<void> writeSubproperties({
  dynamic root,
  String docResult = '',
  String parentPropLookupStr = '',
  bool isRecursiveCall = false,
  dynamic docOptions,
}) async {
  final locals = _WriteSubpropertiesLocals();

  endMain:
  {
    final outputs = await ts.callActiveX(
      root,
      'PropertyObject.GetNumSubProperties',
      inputs: {'lookupString': parentPropLookupStr},
    ); // GetNumSubProperties
    locals.numSubproperties = outputs['Return Value'] as int;
    backToGotoEndWhenDone:
    while (true) {
      if (locals.i == locals.numSubproperties) {
        break endMain;
      }
      final outputs2 = await ts.callActiveX(
        root,
        'PropertyObject.GetNthSubPropertyName',
        inputs: {'lookupString': parentPropLookupStr, 'index': locals.i, 'options': 0},
      ); // GetSubPropName
      locals.subpropName = outputs2['Return Value'] as String;
      parentPropLookupStr != ''
          ? (locals.subpropLookupStr = '$parentPropLookupStr.${locals.subpropName}')
          : (locals.subpropLookupStr = locals.subpropName); // BuildNewLookupStr
      final outputs3 = await ts.callActiveX(
        root,
        'PropertyObject.GetFlags',
        inputs: {'lookupString': locals.subpropLookupStr, 'options': 0},
      ); // GetFlags
      locals.subpropFlags = outputs3['Return Value'] as int;
      locals.subpropFlags & 8 != 0 ? (locals.isHidden = true) : (locals.isHidden = false); // IsHidden
      if (locals.isHidden == false || ts.truthy(docOptions.ShowHidden)) {
        await writePropertyDetails(); // DisplayProperty
      }
      if ((locals.isHidden == false || ts.truthy(docOptions.ShowHidden)) && ts.truthy(docOptions.ShowSubproperties)) {
        await writeSubproperties(); // DisplaySubpropertiesOfSubproperty
      }
      locals.i += 1; // Increment index
      if (isRecursiveCall == false) {
        await ts.callDll(
          '\$(Platform)\\DocSupport.dll',
          'UpdateDocProgressPercent',
          inputs: {'percent_done': locals.i / locals.numSubproperties * 100},
        ); // Update Percent Done
      }
      continue backToGotoEndWhenDone;
    }
  }
}

class _WriteArrayElementsLocals {
  String currentArrayIndex = '';
  int currentOffset = 0;
  int numElements = 0;
  String rowHtml = '<TR>';
  String colHtml = '<TD WIDTH=33% colspan=3 NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>';
}

/// Sequence `Write Array Elements`.
Future<void> writeArrayElements({
  dynamic root,
  ts.Ref<String>? docResult,
  String arrayPropLookupStr = '',
  dynamic docOptions,
}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  final locals = _WriteArrayElementsLocals();

  endMain:
  {
    skipToMaxNumArrayElementsMsg:
    {
      final outputs = await ts.callActiveX(
        root,
        'PropertyObject.GetDimensions',
        inputs: {'lookupString': arrayPropLookupStr, 'options': 0},
      ); // GetNumElements
      locals.numElements = outputs['numElements'] as int;
      backToStartOfLoop:
      while (true) {
        // --- Start of Loop ---
        if (locals.currentOffset == docOptions.MaxNumArrayElementsToShow &&
            locals.currentOffset != locals.numElements) {
          break skipToMaxNumArrayElementsMsg;
        }
        if (locals.currentOffset == locals.numElements) {
          break endMain;
        }
        final outputs2 = await ts.callActiveX(
          root,
          'PropertyObject.GetArrayIndex',
          inputs: {'lookupString': arrayPropLookupStr, 'options': 0, 'offset': locals.currentOffset},
        ); // GetArrayIndexFromOffset
        locals.currentArrayIndex = outputs2['Return Value'] as String;
        await writePropertyDetails(); // DisplayProperty
        await writeSubproperties(); // DisplaySubproperties
        locals.currentOffset += 1; // Inc Loop Var
        continue backToStartOfLoop;
      }
    }
    // --- Max Num Array Elements Msg ---
    docResultRef.value +=
        '${locals.rowHtml + locals.colHtml + arrayPropLookupStr}[...] --- ${ts.resourceString('SEQ_FILE_DOC', 'DOC_MAX_ARRAY_DISPLAY_EXCEEDED')}'; // Add Max Exceeded Msg
  }
}

class _WritePropertyDetailsLocals {
  int valueType = 0;
  bool isObject = false;
  bool isArray = false;
  String typeName = '';
  String subpropValue = '...';
  int subpropFlags = 0;
  String byRefStr = '';
  String rowHtml = '<TR>';
  String propColHtml = '<TD WIDTH=33% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>';
  String typeColHtml = '<TD WIDTH=33% BGCOLOR=GOLDENROD>';
  String valColHtml = '<TD WIDTH=33% BGCOLOR=LIGHTGREEN>';
  String unused = '';
}

/// Sequence `Write Property Details`.
Future<void> writePropertyDetails({
  ts.Ref<String>? docResult,
  dynamic root,
  String propertyToDisplayName = '',
  dynamic docOptions,
}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  final locals = _WritePropertyDetailsLocals();
  final dynamic tryToEvaluateResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  });

  skipToSkipEvaluate:
  {
    final outputs = await ts.callActiveX(
      root,
      'PropertyObject.GetType',
      inputs: {'lookupString': propertyToDisplayName, 'options': 0},
    ); // GetTypeInfo
    locals.valueType = outputs['Return Value'] as int;
    locals.isObject = outputs['isObject'] as bool;
    locals.isArray = outputs['isArray'] as bool;
    locals.typeName = outputs['typeName'] as String;
    // Normally Evaluate() should only fail if the property name has invalid characters in it.
    // --- Test Evaluate Error ---
    try {
      ts.eval('Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName)'); // TryToEvaluate
      tryToEvaluateResult.Status = ts.Status.done;
    } on ts.RunTimeError catch (_) {}
    if (tryToEvaluateResult.Status == 'Error') {
      locals.subpropValue = tryToEvaluateResult.Error.Msg as String; // Document Error
    }
    if (tryToEvaluateResult.Status == 'Error') {
      break skipToSkipEvaluate;
    }
    locals.typeName =
        root.GetPropertyObject(propertyToDisplayName, 0).Type.DisplayString as String; // GetTypeNameForDisplay
    // Get the value of a number, boolean or activex property
    if (locals.valueType == 2 || locals.valueType == 3 || locals.valueType == 5) {
      ts.eval(
        'Locals.SubpropValue = Str(Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName))',
      ); // GetSubPropValue1
    }
    // Get the value of a string property
    if (locals.valueType == 1) {
      ts.eval(
        'Locals.SubpropValue = "\\"" + Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName) + "\\""',
      ); // GetSubPropValue2
    }
    // Get the value of an enum property
    if (ts.cond('Locals.valueType == PropValType_Enum')) {
      ts.eval(
        ' Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName).GetDisplayNames("", PropOption_NoOptions, Locals.Unused, Locals.SubpropValue)',
      ); // GetSubPropValue7
    }
  }
  // --- Skip Evaluate ---
  ts.eval('FindAndReplace(Locals.SubpropValue, "<", "&lt;")'); // Process SubpropValue
  ts.eval('\nFindAndReplace(Locals.SubpropValue, ">", "&gt;")');
  ts.eval('\nFindAndReplace(Locals.SubpropValue, "\\n", "<BR>")');
  final outputs2 = await ts.callActiveX(
    root,
    'PropertyObject.GetFlags',
    inputs: {'lookupString': propertyToDisplayName, 'options': 0},
  ); // GetFlags
  locals.subpropFlags = outputs2['Return Value'] as int;
  locals.subpropFlags & 4 != 0
      ? (locals.byRefStr = ' (${ts.resourceString('SEQUENCING ADAPTER', 'PASS_BYREFERENCE')})')
      : (locals.byRefStr = ''); // IsByRef
  docResultRef.value +=
      '${locals.rowHtml + locals.propColHtml + propertyToDisplayName + locals.typeColHtml + locals.typeName + locals.byRefStr + locals.valColHtml + locals.subpropValue}\n'; // Add Display String
  if (locals.isArray && ts.truthy(docOptions.ShowArrayElements)) {
    await writeArrayElements(); // DisplayArrayElements
  }
}

class _WriteMultipleNumericLimitLimitsLocals {
  int currentOffset = 0;
  int numElements = 0;
  String rowHtml = '<TR>';
  String propColHtml = '<TD WIDTH=30% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>';
  String valColHtml = '<TD WIDTH=70% BGCOLOR=LIGHTGREEN>';
  bool oneLimitOnly = false;
  String lowLimitFmt = '';
  String highLimitFmt = '';
}

/// Sequence `Write Multiple Numeric Limit Limits`.
Future<void> writeMultipleNumericLimitLimits({dynamic step, ts.Ref<String>? docResult}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  final locals = _WriteMultipleNumericLimitLimitsLocals();

  skipToAfterLoop:
  {
    final outputs = await ts.callActiveX(
      step.Result.Measurement,
      'PropertyObject.GetDimensions',
      inputs: {'lookupString': '', 'options': 0},
    ); // GetNumElements
    locals.numElements = outputs['numElements'] as int;
    backToStartOfLoop:
    while (true) {
      // --- Start of Loop ---
      if (locals.currentOffset == locals.numElements) {
        break skipToAfterLoop;
      }
      locals.oneLimitOnly = false; // Initialize Local Variables
      ts.eval(
        '\nParameters.DocResult += Locals.RowHTML+\n"<TD COLSPAN=2 ALIGN=LEFT WIDTH=100% BGCOLOR=TEAL>" + "<FONT COLOR=WHITE>" + ResStr("SEQ_FILE_DOC", "MEAS_NAME_LBL") + " " + NameOf(Parameters.Step.Result.Measurement[Locals.CurrentOffset])  + "</FONT>\\n"\n',
      ); // Header
      if (ts.cond('PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Comp")')) {
        docResultRef.value +=
            '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_COMP_TYPE'), '%-30s') + locals.valColHtml + (step.Result.Measurement[locals.currentOffset].Comp as String)}\n'; // Comparison Type
      }
      if (ts.cond(
        '#NoValidation(\nAllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Comp"), PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.High"), AnyOf(Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "EQ", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "NE", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "GT", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "LT", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "GE", Parameters.Step.Result.Measurement[ Locals.CurrentOffset ].Comp == "LE"))\n)',
      )) {
        locals.oneLimitOnly = true; // One Limit Only?
      }
      if (ts.cond(
        'PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.Low")',
      )) {
        final outputs2 = await ts.callActiveX(
          step.Result.Measurement[locals.currentOffset].Limits.Low,
          'PropertyObject.NumericFormat',
        ); // Get Low Limit Format
        locals.lowLimitFmt = outputs2['Return Value'] as String;
      }
      if (ts.cond(
        'PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.High")',
      )) {
        final outputs3 = await ts.callActiveX(
          step.Result.Measurement[locals.currentOffset].Limits.High,
          'PropertyObject.NumericFormat',
        ); // Get High Limit Format
        locals.highLimitFmt = outputs3['Return Value'] as String;
      }
      if (ts.cond(
        '#NoValidation(AllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.Low"), Parameters.Step.Result.Measurement[Locals.CurrentOffset].Comp != "LOG"))',
      )) {
        docResultRef.value +=
            '${locals.rowHtml + locals.propColHtml + (locals.oneLimitOnly ? ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT') : ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT_LOW')) + locals.valColHtml + ts.str(step.Result.Measurement[locals.currentOffset].Limits.Low, locals.lowLimitFmt)}\n'; // Low Limit
      }
      if (ts.cond(
        '#NoValidation(AllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Limits.High"), Parameters.Step.Result.Measurement[Locals.CurrentOffset].Comp != "LOG", !Locals.OneLimitOnly))',
      )) {
        docResultRef.value +=
            '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_LIMIT_HIGH'), '%-30s') + locals.valColHtml + ts.str(step.Result.Measurement[locals.currentOffset].Limits.High, locals.highLimitFmt)}\n'; // High Limit
      }
      if (ts.cond(
        '#NoValidation(AllOf(PropertyExists("Parameters.Step.Result.Measurement[" + Str(Locals.CurrentOffset) + "].Units"), Parameters.Step.Result.Measurement[Locals.CurrentOffset].Units != ""))',
      )) {
        docResultRef.value +=
            '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_UNITS'), '%-30s') + locals.valColHtml + (step.Result.Measurement[locals.currentOffset].Units as String)}\n'; // Units
      }
      if (ts.cond(
        'AllOf(PropertyExists("Parameters.Step.DataSourceArray[" + Str(Locals.CurrentOffset) + "]"), Parameters.Step.UseIndividualDataSources)',
      )) {
        ts.eval(
          '\nParameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_DATASOURCE"), "%-30s") +\n	Locals.ValColHTML +\n	LocalizeExpression(Parameters.Step.DataSourceArray[Locals.CurrentOffset]) + "\\n"\n',
        ); // Individual Data Source
      }
      locals.currentOffset += 1; // Inc Loop Var
      continue backToStartOfLoop;
    }
  }
  // --- After Loop ---
  if (locals.numElements > 0) {
    docResultRef.value +=
        '${locals.rowHtml}<TD COLSPAN=2 ALIGN=LEFT WIDTH=100% BGCOLOR=TEAL><FONT COLOR=WHITE>${ts.resourceString('SEQ_FILE_DOC', 'END_OF_MEAS_LBL')}</FONT>\n'; // Footer
  }
  if (ts.cond(
    '#NoValidation(AllOf(PropertyExists("Parameters.Step.DataSource"), !Parameters.Step.UseIndividualDataSources, Locals.NumElements > 0))',
  )) {
    ts.eval(
      'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_DATASOURCE"), "%-30s") +\n	Locals.ValColHTML +\n	LocalizeExpression(Parameters.Step.DataSource) + "\\n"\n',
    ); // Data Source
  }
}

class _WriteRequirementsElementsLocals {
  String currentReqElement = '';
  String tmpString = '';
  String rowHtml = '<TR>';
  String propColHtml = '<TD WIDTH=30% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>';
  String valColHtml = '<TD WIDTH=70% BGCOLOR=LIGHTGREEN>';
}

/// Sequence `Write Requirements Elements`.
Future<void> writeRequirementsElements({dynamic requirements, ts.Ref<String>? docResult}) async {
  final docResultRef = docResult ?? ts.Ref<String>('');
  final locals = _WriteRequirementsElementsLocals();

  // Process Requirements
  for (final element in ts.iterate(requirements.Links)) {
    locals.currentReqElement = element as String;
    locals.tmpString += '${locals.currentReqElement}\n'; // Get Requirments
  }
  if (ts.len(locals.tmpString) > 0) {
    ts.eval('FindAndReplace(Locals.tmpString, "<", "&lt;")'); // Requirements
    ts.eval('\nFindAndReplace(Locals.tmpString, ">", "&gt;")');
    ts.eval('\nFindAndReplace(Locals.tmpString, "\\n", "<br>")');
    docResultRef.value +=
        '${locals.rowHtml + locals.propColHtml + ts.str(ts.resourceString('SEQ_FILE_DOC', 'DOC_STEP_REQUIREMENTS'), '%-30s') + locals.valColHtml + locals.tmpString}\n';
  }
}
